// Dynamically generate the point value of a word based on Scrabble scoring.
export function getScrabblePoints(word: string): number {
  const points: { [letter: string]: number } = {
    A: 1, B: 3, C: 3, D: 2, E: 1, F: 4, G: 2, H: 4, I: 1, J: 8, K: 5, L: 1, M: 3,
    N: 1, O: 1, P: 3, Q: 10, R: 1, S: 1, T: 1, U: 1, V: 4, W: 4, X: 8, Y: 4, Z: 10
  };
  let score = 0;
  const uppercase = word.toUpperCase();
  for (let i = 0; i < uppercase.length; i++) {
    const letter = uppercase[i];
    if (points[letter]) {
      score += points[letter];
    }
  }
  return score;
}

